with flattened as (select id, plan, effective_from, currency, explode_outer(tier_limits) as tier_value from price_tiers), base as (select *, upper(plan) as plan_upper from flattened where effective_from >= date '2024-04-14' and plan = 'pro'), with_windows as (select plan, effective_from, plan_upper, rank() over w_grp as tier_value_rank, dense_rank() over w_ordered as tier_value_dense_rank, rank() over w_recent as tier_value_rank_2 from base where currency = 'EUR' window w_grp as (order by tier_value desc nulls first), w_ordered as (order by tier_value desc), w_recent as (partition by plan order by tier_value nulls first)), with_windows_price_tiers as (select *, dense_rank() over (order by tier_value_dense_rank nulls last) as tier_value_dense_rank_dense_rank, avg(tier_value_rank) over (partition by plan) as plan_avg_tier_value_rank, cume_dist() over (order by tier_value_dense_rank) as tier_value_dense_rank_cume_dist from with_windows), cleaned as (select plan, effective_from, plan_upper, tier_value_dense_rank, tier_value_rank_2, tier_value_dense_rank_dense_rank, plan_avg_tier_value_rank, tier_value_dense_rank_cume_dist, tier_value_rank * tier_value_dense_rank as tier_value_rank_times_tier_value_dense_rank from with_windows_price_tiers where tier_value_rank between 4 and 8), filtered as (select *, round(tier_value_dense_rank * 0.85, 2) as tier_value_dense_rank_scaled from cleaned where tier_value_dense_rank_cume_dist is not null), cleaned_price_tiers as (select *, round(tier_value_dense_rank, 2) as tier_value_dense_rank_rounded from filtered where effective_from > date '2024-05-24') select plan, effective_from, plan_upper, tier_value_dense_rank, tier_value_rank_2, plan_avg_tier_value_rank, tier_value_dense_rank_cume_dist, tier_value_dense_rank_scaled, tier_value_dense_rank_rounded from cleaned_price_tiers
